When the old password supplied to ASC_CHGPASSWD is invalid, the function returns the integer constant **AS_NO**. An application should detect this value and inform the caller that the password was not changed because the old password did not match. For example:
```c
rc = ASC_CHGPASSWD(asce, user, oldpass, newpass);
if (rc == AS_OK) {
    printf("Password changed successfully\n");
} else if (rc == AS_NO) {
    printf("Old password is invalid; password not changed\n");
} else {
    printf("Error %d: %s\n", rc, ASC_STRERROR(rc));
}
```
This handling follows the sample code in the Fo Admin Nx driver documentation.

If ASC_CHGPASSWD returns **AS_PASSDUPLICATE**, it indicates that the new password has been used previously for the user and therefore cannot be reused. The application should notify the user that the selected new password is not acceptable because it was used before, and prompt for a different password. Example handling:
```c
rc = ASC_CHGPASSWD(asce, user, oldpass, newpass);
if (rc == AS_PASSDUPLICATE) {
    printf("The new password has been used previously; choose a different password.\n");
}
```

```c
#include <stdio.h>
#include <stdlib.h>
#include <ascauth.h>

/*
 * change_user_password – attempts to change the password for a given user.
 * Parameters:
 *   asce    – pointer to an already‑initialized ASCENV environment.
 *   user    – Enterprise User ID.
 *   oldpass – Current password.
 *   newpass – Desired new password.
 * Returns:
 *   A string describing the outcome. Caller must not free the returned string.
 */
const char *change_user_password(ASCENV *asce, const char *user,
                                 const char *oldpass, const char *newpass)
{
    int rc = ASC_CHGPASSWD(asce, (char *)user, (char *)oldpass, (char *)newpass);
    switch (rc) {
        case AS_OK:
            return "Password changed successfully";
        case AS_NO:
            return "Old password is invalid";
        case AS_NOUSER:
            return "User not found or inactive";
        case AS_REVOKED:
            return "User is disabled";
        case AS_INTRUDER:
            return "Intruder lockout is active for this user";
        case AS_PASSDUPLICATE:
            return "New password has been used previously";
        case AS_PASSTOOSHORT:
            return "New password is too short";
        case AS_BADCLIENT:
            return "Local host not authorized to query the Core Driver";
        case AS_NOAGENT:
            return "No Core Driver could be contacted";
        case AS_NOAUTHENV:
            return "No authentication environment has been established";
        case AS_INVALIDREQ:
            return "Call rejected as not valid or not supported";
        case AS_INVALIDARGS:
            return "Invalid arguments supplied to ASC_CHGPASSWD";
        case AS_KEYEXPIRED:
            return "Old key expired";
        default:
            return ASC_STRERROR(rc);
    }
}
```
